<?php
$user=currentUser();$siteName=setting('site_name','Brainpress');$bottomTabs=mobileTabs();$categories=query('SELECT id,name,parent_id FROM categories ORDER BY id')->fetchAll();
$titles=['login'=>'Sign in','register'=>'Create account','setup'=>'Create administrator','account'=>'Account','forbidden'=>'Administrator access required.'];
?><!doctype html><html lang="<?=language()?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#ffffff"><meta name="csrf" content="<?=e($_SESSION['csrf'])?>"><title><?=e(t($titles[$authPage]))?> · <?=e($siteName)?></title><script src="/assets/theme.js?v=3"></script><link rel="stylesheet" href="/assets/app.css?v=22"><?=languageData()?><script src="/assets/app.js?v=18" defer></script><script src="/assets/auth.js?v=1" defer></script></head><body class="site-body <?=$bottomTabs?'has-mobile-tabs':''?>"><?php require __DIR__.'/site-header.php';?><main class="account-page-main"><section class="panel auth-shell <?=$authPage==='account'?'account-shell':''?>"><h1><?=e(t($titles[$authPage]))?></h1>
<?php if($authPage==='forbidden'):?><p><?=e(t('Only administrators can access the administration area.'))?></p><div class="auth-links"><a href="/account"><?=e(t('Account'))?></a></div>
<?php elseif($authPage==='account'):?>
<p class="auth-note"><?=e($user['display_name'])?> · <?=e(t($user['role']==='admin'?'Administrator':'Member'))?></p><div class="account-actions"><a class="button" href="/?write"><?=e(t('Write a post'))?></a><?php if(isAdministrator()):?><a class="button" href="/admin"><?=e(t('Administration'))?></a><?php endif;?><form data-auth-action="logout"><button class="text-button" type="submit"><?=e(t('Sign out'))?></button><p role="status"></p></form></div><h2><?=e(t('My posts'))?></h2><?php $myPosts=query("SELECT id,title,status FROM posts WHERE user_id=? AND status<>'trash' ORDER BY updated_at DESC LIMIT 100",[$user['id']])->fetchAll();foreach($myPosts as $entry):?><div class="account-post"><span><?=e($entry['title'])?> · <?=e(t(ucfirst($entry['status'])))?></span><a href="/?edit=<?=$entry['id']?>"><?=e(t('Edit'))?></a></div><?php endforeach;?><?php if(!$myPosts):?><p class="auth-note"><?=e(t('No posts yet.'))?></p><?php endif;?><h2 style="margin-top:24px"><?=e(t('Change password'))?></h2><form class="auth-form" data-auth-action="password_change"><label><?=e(t('Current password'))?><input type="password" name="current_password" autocomplete="current-password" required maxlength="72"></label><label><?=e(t('New password'))?><input type="password" name="password" autocomplete="new-password" minlength="10" maxlength="72" required></label><button class="button" type="submit"><?=e(t('Save changes'))?></button><p role="status"></p></form>
<?php elseif($user):?><p><?=e(t('You are already signed in.'))?></p><div class="auth-links"><a href="/account"><?=e(t('Account'))?></a></div>
<?php elseif($authPage==='register'&&setupAvailable()):?><p><?=e(t('Create the administrator first.'))?></p><div class="auth-links"><a href="/setup"><?=e(t('Create administrator'))?></a></div>
<?php else:?>
<?php if($authPage==='setup'):?><p class="auth-note"><?=e(t('Read storage/setup-token.txt in your server file manager and enter its contents below. This token is never shown publicly.'))?></p><?php endif;?>
<form class="auth-form" data-auth-action="<?=$authPage?>"><input type="hidden" name="next" value="<?=e(authNext((string)($_GET['next']??'')))?>">
<?php if($authPage==='setup'):?><label><?=e(t('Setup token'))?><input name="setup_token" autocomplete="off" required maxlength="64"></label><?php endif;?>
<label><?=e(t('Username'))?><input name="username" autocomplete="username" required maxlength="40" <?=$authPage!=='login'?'pattern="[A-Za-z0-9_][A-Za-z0-9_.-]{2,39}"':''?>></label>
<?php if($authPage!=='login'):?><label><?=e(t('Display name'))?><input name="display_name" autocomplete="nickname" maxlength="80"></label><?php endif;?>
<label><?=e(t('Password'))?><input name="password" type="password" autocomplete="<?=$authPage==='login'?'current-password':'new-password'?>" required <?=$authPage!=='login'?'minlength="10"':''?> maxlength="72"></label>
<?php if($authPage!=='login'):?><p class="auth-note"><?=e(t('Use a password of 10–72 bytes.'))?></p><?php endif;?>
<button class="button" type="submit"><?=e(t($titles[$authPage]))?></button><p role="status" aria-live="polite"></p></form>
<div class="auth-links"><?php if($authPage==='login'):?><?php if(setupAvailable()):?><a href="/setup"><?=e(t('Create administrator'))?></a><?php else:?><a href="/register"><?=e(t('Create account'))?></a><?php endif;?><?php else:?><a href="/login"><?=e(t('Sign in'))?></a><?php endif;?></div>
<?php endif;?></section></main><footer class="site-footer"><?php renderFooterInfo($siteName);?></footer><?php require __DIR__.'/site-tabs.php';require __DIR__.'/site-panels.php';?></body></html>
